import React, { Dispatch } from 'react';

import { FormFieldMessagesReducerAction } from '../state/formfield-messages-state-reducer.js';

export interface FormFieldCustomMessage {
  variant: 'error' | 'hint';
  id: string;
  messageType?: 'custom' | 'formcontrol';
}

export interface FormFieldControlMessage extends FormFieldCustomMessage {
  message: React.ReactNode;
  validityStateKey: string;
}

export type FormFieldMessage = FormFieldCustomMessage | FormFieldControlMessage;

export interface FormFieldMessageContextState {
  formControlMessages: FormFieldControlMessage[];
  customMessages: FormFieldCustomMessage[];
  hasError: boolean;
  isDirty?: boolean;
  controlId?: string;
}

export interface FormFieldMessageContextProps {
  controlId?: string;
  /**
   * @defaultValue false
   */
  disabled?: boolean;
  dispatch: Dispatch<FormFieldMessagesReducerAction>;
  state: FormFieldMessageContextState;
}

export const initialState = {
  formControlMessages: [],
  customMessages: [],
  hasError: false,
  isDirty: false,
};

/**
 * Context provider for `FormFieldMessageContextProps` to connect form controls to the applied errors and error messages.
 */
export const FormFieldMessageContext =
  React.createContext<FormFieldMessageContextProps>({
    state: initialState,
    dispatch: () => null,
  });
